import{_ as s,o as e,c as p,a2 as t}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"正月","description":"","frontmatter":{"title":"正月","date":"2026-11-08T00:00:00.000Z","seq":32,"categories":["美文","诗经"],"collection":"《诗经 · 小雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·小雅/正月.md","filePath":"blogs/诗经·小雅/正月.md"}'),o={name:"blogs/诗经·小雅/正月.md"};function c(l,a,n,r,m,_){return e(),p("div",null,[...a[0]||(a[0]=[t('<h1 id="正月" tabindex="-1">正月 <a class="header-anchor" href="#正月" aria-label="Permalink to &quot;正月&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　节南山之什</p><div class="poem"><p class="poem-stanza">正月繁霜，我心忧伤。民之讹言，亦孔之将。念我独兮，忧心京京。哀我小心，癙忧以痒。</p><p class="poem-stanza">父母生我，胡俾我瘉？不自我先，不自我后。好言自口，莠言自口。忧心愈愈，是以有侮。</p><p class="poem-stanza">忧心惸惸，念我无禄。民之无辜，并其臣仆。哀我人斯，于何从禄？瞻乌爰止？于谁之屋？</p><p class="poem-stanza">瞻彼中林，侯薪侯蒸。民今方殆，视天梦梦。既克有定，靡人弗胜。有皇上帝，伊谁云憎？</p><p class="poem-stanza">谓山盖卑，为冈为陵。民之讹言，宁莫之惩。召彼故老，讯之占梦。具曰予圣，谁知乌之雌雄！</p><p class="poem-stanza">谓天盖高，不敢不局。谓地盖厚，不敢不蹐。维号斯言，有伦有脊。哀今之人，胡为虺蜴？</p><p class="poem-stanza">瞻彼阪田，有菀其特。天之杌我，如不我克。彼求我则，如不我得。执我仇仇，亦不我力。</p><p class="poem-stanza">心之忧矣，如或结之。今兹之正，胡然厉矣？燎之方扬，宁或灭之？赫赫宗周，褒姒灭之！</p><p class="poem-stanza">终其永怀，又窘阴雨。其车既载，乃弃尔辅。载输尔载，将伯助予！</p><p class="poem-stanza">无弃尔辅，员于尔辐。屡顾尔仆，不输尔载。终逾绝险，曾是不意。</p><p class="poem-stanza">鱼在于沼，亦匪克乐。潜虽伏矣，亦孔之炤。忧心惨惨，念国之为虐！</p><p class="poem-stanza">彼有旨酒，又有嘉肴。洽比其邻，婚姻孔云。念我独兮，忧心殷殷。</p><p class="poem-stanza">佌佌彼有屋，蔌蔌方有谷。民今之无禄，天夭是椓。哿矣富人，哀此惸独。</p></div>',3)])])}const z=s(o,[["render",c]]);export{d as __pageData,z as default};
